// Continues only when TrendsFast already holds a confirmed brand context.
const context = $input.first().json.context;
if (!context || context.kind !== 'CONFIRMED_CONTEXT' || !context.context_id) {
  throw new Error('No confirmed brand context yet. Set up your brand in the TrendsFast dashboard first. Nothing was spent.');
}
return [{ json: { context_id: context.context_id } }];

// Lists the top five trending items with their signal and, when known, their topic's stage.
const result = $input.first().json;
const items = Array.isArray(result.data?.items) ? result.data.items : [];
const lines = items.slice(0, 5).map((item, index) => {
  const observation = item.current_observation ?? {};
  const stage = item.topic_history?.state ? `, ${item.topic_history.state.toLowerCase()}` : '';
  return `${index + 1}. ${observation.title ?? 'Untitled'} (${item.entity?.platform ?? 'unknown'}, ${item.signal}${stage})\n   ${item.entity?.original_url ?? 'no link'}`;
});
return [{
  json: {
    text: lines.length
      ? lines.join('\n')
      : 'Nothing is trending for your brand right now. An empty result costs 0 credits.',
    result_id: result.result_id,
    request_id: result.request_id,
    replayed: result.usage?.replayed === true,
  },
}];

// No answer, a 409 or a 5xx means the paid call may still have run: read it back for free.
const failed = $input.first().json;
const status = failed.http_status;
const outcomeUnknown = status === undefined || status === 409 || status >= 500;
if (!failed.request_id || !outcomeUnknown) {
  throw new Error(`TrendsFast did not run this request, so there is nothing to recover: ${failed.error}`);
}
return [{ json: { request_id: failed.request_id } }];
